// Import of required libraries
import { test, getBaseUrl, newSkyrampPlaywrightPage, expect } from '@skyramp/skyramp';
import { placeOrder } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/logout`);
    await page.goto(`${baseUrl}/product/0PUK6V6EV0`);
    await page.getByRole("button", { name: "Add To Cart" }).click();
    await page.waitForLoadState('networkidle');
    await expect(page.locator('#cart-count-badge')).toHaveText('1');

    await placeOrder(page);
    await expect(page).toHaveURL(`${baseUrl}/cart/checkout`);
    await expect(page.getByRole('heading', { name: 'Your order is complete!' })).toBeVisible();

    // The badge markup and its stylesheet DO ship on the confirmation page...
    await expect(page.locator('#cart-count-badge')).toHaveCount(1);
    await expect(page.locator('link[href*="header.css"]')).toHaveCount(1);
    await expect(page.locator('#cart-count-badge')).toBeHidden();

    // ...but cart-badge.js does NOT. The <script> tag was placed inside
    // {{ if $.show_currency }} in header.html, and the order handler sets
    // show_currency:false (handlers.go:393), so the badge's own script never
    // loads on this page. EXPECTED TO FAIL until the script tag is hoisted
    // out of the currency block.
    await expect(page.locator('script[src*="cart-badge.js"]')).toHaveCount(1);
});
